import openpyxl
import os
from collections import defaultdict

in_path = os.environ['IN_XLSX']
out_path = os.environ['OUT_XLSX']

wb = openpyxl.load_workbook(in_path)
ws = wb.active

# Collect data: Name (col A), Entry Time (col I)
rows_data = []
for row in range(2, 42):
    name = ws.cell(row=row, column=1).value  # A
    entry_time = ws.cell(row=row, column=9).value  # I
    rows_data.append((row, name, entry_time))

# Find max entry time per name
max_times = defaultdict(lambda: None)
for row, name, et in rows_data:
    if et is not None:
        if max_times[name] is None or et > max_times[name]:
            max_times[name] = et

# Write results to column M
for row, name, et in rows_data:
    if et is not None and max_times[name] is not None:
        if et == max_times[name]:
            ws.cell(row=row, column=13).value = 'Latest'
        else:
            ws.cell(row=row, column=13).value = 'Not Latest'
    else:
        ws.cell(row=row, column=13).value = None

wb.save(out_path)
print("Done. Saved to", out_path)
